157	
158	  const documentItems = useMemo(
159	    () =>
160	      linkedAttachments
161	        .filter((attachment) => !isVisualAttachment(attachment) && !isAudioAttachment(attachment))
162	        .map((attachment) => toLibraryListItem(attachment, locale)),
163	    [linkedAttachments, locale],
