188			close(done)
189		}()
190	
191		select {
192		case <-done:
193		case <-ctx.Done():
194			select {
195			case <-done:
196				return
197			default:
198			}
199			slog.Error("failed to stop background runners", slog.String("error", ctx.Err().Error()))
200		}
201	}
